import"https://cdn.jsdelivr.net/npm/chart.js";const u="http://localhost:3000/api";document.getElementById("register-form").addEventListener("submit",async e=>{e.preventDefault();const n=e.target,o=document.getElementById("error-message"),t=n.querySelector('button[type="submit"]');o.classList.add("hidden"),t.disabled=!0,t.textContent="Creando cuenta...";const c=document.getElementById("name").value,d=document.getElementById("email").value,l=document.getElementById("password").value,m=document.getElementById("confirm-password").value;if(l!==m){o.textContent="Las contraseñas no coinciden",o.classList.remove("hidden"),t.disabled=!1,t.textContent="Crear Cuenta";return}try{const r=await fetch(`${u}/auth/register`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:c,email:d,password:l})}),s=await r.json();if(!r.ok)throw new Error(s.error||s.errors?.[0]?.msg||"Error al registrarse");localStorage.setItem("token",s.token),localStorage.setItem("user",JSON.stringify(s.user)),window.location.href="/dashboard"}catch(r){o.textContent=r.message,o.classList.remove("hidden"),t.disabled=!1,t.textContent="Crear Cuenta"}});const a=document.querySelector(".login-header"),i=document.querySelector(".login-form"),y=document.querySelectorAll(".form-group");setTimeout(()=>{a.style.transition="all 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94)",a.style.opacity="1",a.style.transform="translateY(0)"},100);setTimeout(()=>{i.style.transition="all 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94)",i.style.opacity="1",i.style.transform="translateY(0) scale(1)"},300);y.forEach((e,n)=>{setTimeout(()=>{e.style.transition="all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94)",e.style.opacity="1",e.style.transform="translateX(0)"},500+n*100)});localStorage.getItem("token")&&(window.location.href="/dashboard");
